import Foundation
import CommonCrypto

// MARK: - Permission Token System

struct PermissionToken: Hashable {
    let userId: String
    let resource: String
    let grantedLevel: AccessLevel
    let timestamp: Date
    let nonce: UInt64

    // Hashable conformance for cache lookup
    func hash(into hasher: inout Hasher) {
        hasher.combine(userId)
        hasher.combine(resource)
    }

    static func == (lhs: PermissionToken, rhs: PermissionToken) -> Bool {
        return lhs.userId == rhs.userId && lhs.resource == rhs.resource
    }
}

enum AccessLevel: Int, Comparable {
    case none = 0
    case read = 1
    case write = 2
    case admin = 3

    static func < (lhs: AccessLevel, rhs: AccessLevel) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

// MARK: - Resource Registry

struct Resource {
    let name: String
    let requiredLevel: AccessLevel
    let handler: (String, [String]) -> String
}

// MARK: - User Database

class UserStore {
    private var users: [String: UserRecord] = [:]

    struct UserRecord {
        let userId: String
        let passwordHash: String
        var baseAccessLevel: AccessLevel
    }

    func authenticate(userId: String, password: String) -> UserRecord? {
        guard let record = users[userId] else { return nil }
        let inputHash = sha256(password)
        guard inputHash == record.passwordHash else { return nil }
        return record
    }

    func register(userId: String, password: String, level: AccessLevel) {
        let hash = sha256(password)
        users[userId] = UserRecord(userId: userId, passwordHash: hash, baseAccessLevel: level)
    }

    private func sha256(_ input: String) -> String {
        let data = Data(input.utf8)
        var hash = [UInt8](repeating: 0, count: Int(CC_SHA256_DIGEST_LENGTH))
        data.withUnsafeBytes { CC_SHA256($0.baseAddress, CC_LONG(data.count), &hash) }
        return hash.map { String(format: "%02x", $0) }.joined()
    }
}

// MARK: - Authorization Cache

class AuthorizationCache {
    private var grantedTokens: Set<PermissionToken> = []
    private let cacheTTL: TimeInterval = 300 // 5 minutes

    /// Records a successful authorization for future fast-path lookup
    func recordGrant(token: PermissionToken) {
        grantedTokens.insert(token)
    }

    /// Checks if a matching authorization has been previously granted
    func checkCachedAuthorization(for token: PermissionToken) -> PermissionToken? {
        // Look up by hash/equality (userId + resource)
        if let cached = grantedTokens.first(where: { $0 == token }) {
            // Verify TTL
            if Date().timeIntervalSince(cached.timestamp) < cacheTTL {
                return cached
            } else {
                grantedTokens.remove(cached)
                return nil
            }
        }
        return nil
    }

    func invalidateUser(_ userId: String) {
        grantedTokens = grantedTokens.filter { $0.userId != userId }
    }
}

// MARK: - Access Controller

class AccessController {
    let userStore = UserStore()
    let cache = AuthorizationCache()
    private var resources: [String: Resource] = [:]

    init() {
        setupResources()
        setupUsers()
    }

    private func setupResources() {
        resources["read_config"] = Resource(
            name: "read_config",
            requiredLevel: .read,
            handler: { user, args in "Config: {debug: false, env: production}" }
        )
        resources["write_config"] = Resource(
            name: "write_config",
            requiredLevel: .write,
            handler: { user, args in "Config updated: \(args.joined(separator: ", "))" }
        )
        resources["delete_user"] = Resource(
            name: "delete_user",
            requiredLevel: .admin,
            handler: { user, args in "User \(args.first ?? "unknown") deleted by \(user)" }
        )
        resources["view_secrets"] = Resource(
            name: "view_secrets",
            requiredLevel: .admin,
            handler: { user, args in "SECRET_API_KEY=sk-prod-9x8f7g6h5j4k3l2" }
        )
    }

    private func setupUsers() {
        userStore.register(userId: "admin", password: "sup3rs3cur3", level: .admin)
        userStore.register(userId: "editor", password: "wr1t3r_pw", level: .write)
        userStore.register(userId: "viewer", password: "r3ad0nly", level: .read)
    }

    /// Main access control entry point
    func accessResource(userId: String, password: String, resourceName: String, args: [String] = []) -> String {
        // Step 1: Authenticate
        guard let user = userStore.authenticate(userId: userId, password: password) else {
            return "ERROR: Authentication failed"
        }

        // Step 2: Look up resource
        guard let resource = resources[resourceName] else {
            return "ERROR: Resource '\(resourceName)' not found"
        }

        // Step 3: Build a permission token for this request
        let requestToken = PermissionToken(
            userId: userId,
            resource: resourceName,
            grantedLevel: user.baseAccessLevel,
            timestamp: Date(),
            nonce: UInt64.random(in: 0...UInt64.max)
        )

        // Step 4: Check cache for previously granted authorization
        if let cachedToken = cache.checkCachedAuthorization(for: requestToken) {
            // Fast path: use cached authorization level
            if cachedToken.grantedLevel >= resource.requiredLevel {
                return resource.handler(userId, args)
            }
        }

        // Step 5: Full authorization check
        guard user.baseAccessLevel >= resource.requiredLevel else {
            return "ERROR: Access denied. Required: \(resource.requiredLevel), Have: \(user.baseAccessLevel)"
        }

        // Step 6: Cache the successful authorization
        cache.recordGrant(token: requestToken)

        // Step 7: Execute
        return resource.handler(userId, args)
    }
}

